PartialSink.swift:writeTableString.code:
@inline(never)
  private mutating func writeTableString(
    _ entry: UnsafePointer<StreamFieldEntry>,
    frame: UnsafeMutablePointer<BorrowedFrame>,
    _ bytes: Span<UInt8>
  ) -> StreamApplyResult {
    let storage = frame.pointee.storage
    let member = storage + Int(entry.pointee.offset)
    switch entry.pointee.kind {
    case .streamString:
      if entry.pointee.isOptional {
        _streamMaterializeOptional(member, as: StreamString.self)
      }
      let string = member.assumingMemoryBound(to: StreamString.self)
      if entry.pointee.capacity > 0 {
        string.pointee.streamReserve(utf8ByteCount: Int(entry.pointee.capacity))
      }
      if bytes.count > 0 { string.pointee.streamAppend(utf8: bytes) }
      return .applied
    case .inlineString:
      if entry.pointee.isOptional {
        Self.materializeInlineString(member, capacity: entry.pointee.capacity)
      }
      return _streamInlineStringAppend(member, capacity: entry.pointee.capacity, bytes)
    case .custom:
      let opened = withUnsafeTemporaryAllocation(of: UInt8.self, capacity: 1) { buffer in
        let empty = UnsafeBufferPointer(start: buffer.baseAddress, count: 0)
        return frame.pointee.schema.applyString(
          storage, entry.pointee.index, Span(_unsafeElements: empty)
        )
      }
      if opened != .applied { return opened }
      if bytes.count > 0 {
        return frame.pointee.schema.applyString(storage, entry.pointee.index, bytes)
      }
      return .applied
    default:
      return .unsupported
    }
  }

PartialsStream.swift:PartialsStream.comment:
Drives a parser and exposes each incremental value state.

```swift
@StreamParseable
struct BlogPost {
  var title: String = ""
}

var stream = PartialsStream(initialValue: BlogPost.Partial(), from: .json())
for byte in #"{"title":"DocC"}"#.utf8 {
  _ = try stream.next(byte)
}
let final = try stream.finish()
```

The value lives in its own allocation rather than inline. Frames inside the sink hold pointers
into it so partials update at every depth as bytes arrive, and those pointers have to survive
the stream being moved, which a stored property would not.

PartialsStream.swift:finish.code:
@inlinable
  @discardableResult
  public mutating func finish() throws -> Value {
    guard !self.hasParserThrown else { throw StreamParsingError.parserThrows }
    guard !self.hasFinished else { throw StreamParsingError.parserFinished }
    self.hasFinished = true
    do {
      try self.parser.finish(into: &self.sink)
    } catch {
      self.hasParserThrown = true
      throw error
    }
    return self.current
  }

PartialsStream.swift:finishValue.code:
@inlinable
  public consuming func finishValue() throws -> Value {
    guard !self.hasParserThrown else { throw StreamParsingError.parserThrows }
    guard !self.hasFinished else { throw StreamParsingError.parserFinished }
    try self.parser.finish(into: &self.sink)
    // Move rather than read: `storage.move()` transfers the tree bitwise, so no copy is made.
    // The slot is refilled with the empty initial value for the deinit to destroy — a tree of
    // nils, which costs a few outlined destroys instead of a walk over everything that was
    // parsed. (`discard self` would skip even that, but it requires every stored property to be
    // trivially destroyed, and the parser and sink own buffers.)
    let value = self.storage.move()
    self.storage.initialize(to: Value.streamInitialValue())
    return value
  }

@inlinable
  public mutating func finishValue(
    resettingTo initialValue: Value = Value.streamInitialValue()
  ) throws -> Value {
    guard !self.hasParserThrown else { throw StreamParsingError.parserThrows }
    guard !self.hasFinished else { throw StreamParsingError.parserFinished }
    do {
      try self.parser.finish(into: &self.sink)
    } catch {
      self.hasParserThrown = true
      throw error
    }
    let value = self.storage.move()
    self.storage.initialize(to: initialValue)
    self.parser.reset()
    self.sink.reset()
    return value
  }

