@inlinable
@inline(__always)
func streamFieldHash(word: UInt64, length: UInt16) -> UInt64 {
  var z = word ^ (UInt64(length) &<< 56)
  z = (z ^ (z >> 33)) &* 0xff51afd7ed558ccd
  z = (z ^ (z >> 33)) &* 0xc4ceb9fe1a85ec53
  z = z ^ (z >> 33)
  return z
}

